1	//! Hash table — 1:1 port of `sqlite-source/src/hash.c`.
2	//!
3	//! Implements the generic hash table used throughout SQLite, plus a
4	//! generic `GrowableArray<T>` for code that needs a growable vector.
5	//!
6	//! # C source correspondence
7	//!
8	//! | Rust item                 | C source                          |
9	//! |--------------------------|-----------------------------------|
10	//! | `str_hash`               | `strHash` (hash.c:55-73)          |
11	//! | `Hash::new`              | `sqlite3HashInit` (hash.c:23-29)  |
12	//! | `Hash::clear`            | `sqlite3HashClear` (hash.c:35-50) |
13	//! | `Hash::find`             | `sqlite3HashFind` (hash.c:222-226)|
14	//! | `Hash::insert`           | `sqlite3HashInsert` (hash.c:242)  |
15	//! | `find_element_with_hash` | `findElementWithHash` (hash.c:153)|
16	//! | `insert_element`         | `insertElement` (hash.c:79-104)   |
17	//! | `remove_element`         | `removeElement` (hash.c:188-216)  |
18	//! | `rehash`                 | `rehash` (hash.c:113-146)         |
19	//!
20	//! # Behavior contract (1:1 with C)
21	//!
22	//! - **Knuth multiplicative hash** with constant `0x9e3779b1`,
23	//!   ASCII chars masked with `0xdf` (so `A` and `a` hash equal).
24	//! - **Chain table** for collision (each bucket holds a `chain` head +
25	//!   `count`); the spec's "linear probing" wording is a misnomer for the
26	//!   C source's chained implementation — we follow C per
27	//!   `02-c-porting-conventions.md` §1.
28	//! - **Rehash trigger**: `count >= 5 && count > 2*htsize` → rehash to
29	//!   `count*3` buckets (hash.c:267-269).
30	//! - **O(N) iteration** via the doubly-linked `first → next` chain that
31	//!   mirrors the C-side `Hash.first` linked list.
32	//! - **`data == null`** is the sentinel for "this slot is empty" — the
33	//!   insert API uses `data == null` to mean "remove this entry",
34	//!   matching `sqlite3HashInsert` semantics.
35	//! - **OOM contract**: if `Box`-style growth fails (it cannot on the
36	//!   default Rust allocator, but we model the path), `insert` returns
37	//!   the input `data` unchanged and the table is left untouched,
38	//!   matching `hash.c:262`.
39	//!
40	//! # String vs integer keys
41	//!
42	//! The C version's `pKey` is always a `const char*`; integer keys are
43	//! formatted to strings by callers (e.g. `printf("%lld", ...)`). We
44	//! mirror this by always storing a `String` and expose `insert_int` /
45	//! `find_int` helpers that format the integer first.
46	
47	use std::ptr;
48	
49	use crate::error::{SqliteError, SqliteResult};
50	
51	// ============================================================================
52	// strHash — Knuth multiplicative hash, matches C (hash.c:55-73)
53	// ============================================================================
54	
55	/// `strHash` (hash.c:55-73) — Knuth multiplicative hashing constant
56	/// `0x9e3779b1` (2654435761), the closest prime to
57	/// `(2**32) * golden_ratio`.
58	///
59	/// ASCII characters are masked with `0xdf` so that `A`/`a`, `B`/`b`,
60	/// etc. hash to the same value (matching the C version's case-insensitive
61	/// ASCII folding).
62	#[inline]
63	pub fn str_hash(z: &str) -> u32 {
64	    let mut h: u32 = 0;
65	    for &b in z.as_bytes() {
66	        h = h.wrapping_add((b & 0xdf) as u32);
67	        h = h.wrapping_mul(0x9e3779b1);
68	    }
69	    h
70	}
71	
72	// ============================================================================
73	// Hash table types
74	// ============================================================================
75	
76	/// Bucket entry — `chain` head pointer + `count` of elements in the chain.
77	#[derive(Clone, Copy, Default)]
78	struct HashEntry {
79	    /// Index into `elems` of the head element, or `None` if bucket is empty.
80	    chain: Option<usize>,
81	    /// Number of elements in this bucket's chain.
82	    count: u32,
83	}
84	
85	/// Element node stored in the hash table.
86	///
87	/// `data` is an opaque `*mut u8` matching the C `void*` payload
88	/// convention. The pointer is never dereferenced by the hash table;
89	/// the caller is responsible for its lifetime.
90	struct HashElem {
91	    p_key: String,
92	    h: u32,
93	    data: *mut u8,
94	    next: Option<usize>,
95	    prev: Option<usize>,
96	    /// `false` when this slot is in the free list.
97	    used: bool,
98	}
99	
100	// ============================================================================
101	// Hash
102	// ============================================================================
103	
104	/// Generic hash table — 1:1 port of C `struct Hash` (hash.c).
105	///
106	/// The data field is an opaque `*mut u8`; for type safety in pure-Rust
107	/// callers, the free functions `insert_boxed` / `find_boxed` wrap
108	/// `Box<T>` storage that this `Hash` only knows as an address.
109	pub struct Hash {
110	    /// Index into `elems` of the first element in the all-elements
111	    /// doubly-linked list (`None` when empty). Mirrors `Hash.first`.
112	    first: Option<usize>,
113	    /// Total number of live elements. Mirrors `Hash.count`.
114	    count: u32,
115	    /// Number of buckets in `ht`. Mirrors `Hash.htsize`. `0` means no
116	    /// bucket array allocated.
117	    htsize: u32,
118	    /// Bucket array. Empty when `htsize == 0`.
119	    ht: Vec<HashEntry>,
120	    /// Element pool indexed by slot id. Live elements + free-list nodes.
121	    elems: Vec<HashElem>,
122	    /// Free list head — slot ids in `elems` that are available for reuse.
123	    free_head: Option<usize>,
124	}
125	
126	impl Default for Hash {
127	    fn default() -> Self {
128	        Self::new()
129	    }
130	}
131	
132	impl Hash {
133	    /// `sqlite3HashInit` (hash.c:23-29) — construct an empty hash table.
134	    pub const fn new() -> Self {
135	        Self {
136	            first: None,
137	            count: 0,
138	            htsize: 0,
139	            ht: Vec::new(),
140	            elems: Vec::new(),
141	            free_head: None,
142	        }
143	    }
144	
145	    /// `sqlite3HashInit` (hash.c:23-29) — re-initialize an existing
146	    /// `Hash` to the empty state without dropping the `String`s already
147	    /// stored in `elems`. Use `clear` to also free those.
148	    pub fn init(&mut self) {
149	        self.first = None;
150	        self.count = 0;
151	        self.htsize = 0;
152	        self.ht.clear();
153	        self.htshrink_to_fit();
154	        self.elems.clear();
155	        self.free_head = None;
156	    }
157	
158	    /// `sqlite3HashClear` (hash.c:35-50) — drop all elements and free
159	    /// the bucket array. The `Hash` is left in the same state as
160	    /// `new()`.
161	    pub fn clear(&mut self) {
162	        // Dropping `elems` drops the Strings automatically.
163	        self.first = None;
164	        self.count = 0;
165	        self.htsize = 0;
166	        self.ht.clear();
167	        self.htshrink_to_fit();
168	        self.elems.clear();
169	        self.free_head = None;
170	    }
171	
172	    /// `sqlite3HashFind` (hash.c:222-226) — look up `p_key`.
173	    ///
174	    /// Returns the stored `data` pointer, or `null_mut()` if the key
175	    /// is not present. Comparison is case-insensitive on ASCII,
176	    /// matching `sqlite3StrICmp`'s contract.
177	    pub fn find(&self, p_key: &str) -> *mut u8 {
178	        self.find_with_hash(p_key).data
179	    }
180	
181	    /// Look up `p_key` returning both the data and the hash, useful for
182	    /// follow-up `insert` / `remove` calls. Mirrors the C-side
183	    /// `findElementWithHash`.
184	    pub fn find_with_hash(&self, p_key: &str) -> FindResult {
185	        let h = str_hash(p_key);
186	        if self.htsize > 0 {
187	            // SAFETY: htsize > 0 → ht.len() == htsize → index in range.
188	            let idx = (h % self.htsize) as usize;
189	            let entry = &self.ht[idx];
190	            let mut count = entry.count;
191	            let mut cur = entry.chain;
192	            while count > 0 {
193	                let slot = cur.expect("chain count > 0 implies chain is Some");
194	                let e = &self.elems[slot];
195	                if e.h == h && str_icmp(&e.p_key, p_key) == 0 {
196	                    return FindResult {
197	                        data: e.data,
198	                        h,
199	                        found: true,
200	                    };
201	                }
202	                cur = e.next;
203	                count -= 1;
204	            }
205	        } else {
206	            // No bucket array — linear search the all-elements list.
207	            let mut count = self.count;
208	            let mut cur = self.first;
209	            while count > 0 {
210	                let slot = cur.expect("count > 0 implies first is Some");
211	                let e = &self.elems[slot];
212	                if e.h == h && str_icmp(&e.p_key, p_key) == 0 {
213	                    return FindResult {
214	                        data: e.data,
215	                        h,
216	                        found: true,
217	                    };
218	                }
219	                cur = e.next;
220	                count -= 1;
221	            }
222	        }
223	        FindResult {
224	            data: ptr::null_mut(),
225	            h,
226	            found: false,
227	        }
228	    }
229	
230	    /// `sqlite3HashInsert` (hash.c:242-272).
231	    ///
232	    /// - If `p_key` already exists:
233	    ///   - If `data` is non-null: replace, return the **old** data.
234	    ///   - If `data` is null: remove the entry, return the old data.
235	    /// - If `p_key` does not exist:
236	    ///   - If `data` is null: no-op, return null.
237	    ///   - If `data` is non-null: insert, return null.
238	    /// - On allocation failure: return `data` unchanged.
239	    pub fn insert(&mut self, p_key: &str, data: *mut u8) -> *mut u8 {
240	        let found = self.find_with_hash(p_key);
241	        if found.found {
242	            let old = found.data;
243	            if data.is_null() {
244	                self.remove_with_hash(found.h);
245	            } else {
246	                // Replace data + key reference. The C version stores
247	                // pKey verbatim; we own a String copy.
248	                let slot = self.find_slot(p_key, found.h)
249	                    .expect("just verified found");
250	                let e = &mut self.elems[slot];
251	                e.data = data;
252	                e.p_key.clear();
253	                e.p_key.push_str(p_key);
254	            }
255	            return old;
256	        }
257	        if data.is_null() {
258	            return ptr::null_mut();
259	        }
260	        // Allocate a new element slot.
261	        let new_h = found.h;
262	        let slot = match self.alloc_slot() {
263	            Some(s) => s,
264	            None => return data, // OOM: hash.c:262
265	        };
266	        {
267	            let e = &mut self.elems[slot];
268	            e.p_key.clear();
269	            e.p_key.push_str(p_key);
270	            e.h = new_h;
271	            e.data = data;
272	            e.next = None;
273	            e.prev = None;
274	            e.used = true;
275	        }
276	        self.count += 1;
277	        // Rehash trigger: count >= 5 && count > 2*htsize (hash.c:267).
278	        if self.count >= 5 && self.count > 2 * self.htsize {
279	            self.rehash(self.count * 3);
280	        }
281	        // Determine target bucket (rehash may have moved us to a new
282	        // bucket layout).
283	        let bucket = if self.htsize > 0 {
284	            Some((new_h % self.htsize) as usize)
285	        } else {
286	            None
287	        };
288	        self.insert_element(bucket, slot);
289	        ptr::null_mut()
290	    }
291	
292	    /// Convenience: insert with an integer key (formatted as decimal).
293	    pub fn insert_int(&mut self, key: i64, data: *mut u8) -> *mut u8 {
294	        // Use a stack buffer for typical sizes; fallback to a String
295	        // for the long-tail.
296	        let mut buf = itoa_buf();
297	        let s = format_i64(key, &mut buf);
298	        self.insert(&s, data)
299	    }
300	
301	    /// Convenience: find by integer key.
302	    pub fn find_int(&self, key: i64) -> *mut u8 {
303	        let mut buf = itoa_buf();
304	        let s = format_i64(key, &mut buf);
305	        self.find(&s)
306	    }
307	
308	    /// Number of live elements in the table.
309	    pub fn len(&self) -> u32 {
310	        self.count
311	    }
312	
313	    /// `true` when no elements are stored.
314	    pub fn is_empty(&self) -> bool {
315	        self.count == 0
316	    }
317	
318	    /// Number of buckets currently allocated (0 means no bucket array).
319	    pub fn htsize(&self) -> u32 {
320	        self.htsize
321	    }
322	
323	    /// Iterate all (key, data) pairs in insertion order (the order of
324	    /// the all-elements doubly-linked list, which matches the C
325	    /// `Hash.first` chain).
326	    pub fn iter(&self) -> HashIter<'_> {
327	        HashIter {
328	            ht: self,
329	            cur: self.first,
330	        }
331	    }
332	
333	    // ------------------------------------------------------------------
334	    // Internal helpers
335	    // ------------------------------------------------------------------
336	
337	    /// Find the slot index of an element matching `p_key` and `h`.
338	    /// Pre-condition: the element is known to be present.
339	    fn find_slot(&self, p_key: &str, h: u32) -> Option<usize> {
340	        if self.htsize > 0 {
341	            let idx = (h % self.htsize) as usize;
342	            let entry = &self.ht[idx];
343	            let mut count = entry.count;
344	            let mut cur = entry.chain;
345	            while count > 0 {
346	                let slot = cur?;
347	                let e = &self.elems[slot];
348	                if e.h == h && str_icmp(&e.p_key, p_key) == 0 {
349	                    return Some(slot);
350	                }
351	                cur = e.next;
352	                count -= 1;
353	            }
354	        }
355	        let mut count = self.count;
356	        let mut cur = self.first;
357	        while count > 0 {
358	            let slot = cur?;
359	            let e = &self.elems[slot];
360	            if e.h == h && str_icmp(&e.p_key, p_key) == 0 {
361	                return Some(slot);
362	            }
363	            cur = e.next;
364	            count -= 1;
365	        }
366	        None
367	    }
368	
369	    /// `insertElement` (hash.c:79-104).
370	    fn insert_element(&mut self, bucket: Option<usize>, slot: usize) {
371	        // First, splice into the all-elements doubly-linked list.
372	        let head = if let Some(b) = bucket {
373	            let entry = &mut self.ht[b];
374	            let head = if entry.count > 0 { entry.chain } else { None };
375	            entry.count += 1;
376	            entry.chain = Some(slot);
377	            head
378	        } else {
379	            None
380	        };
381	        if let Some(head_slot) = head {
382	            // Insert `slot` at the head of `head_slot`'s chain.
383	            let prev = self.elems[head_slot].prev;
384	            self.elems[slot].next = Some(head_slot);
385	            self.elems[slot].prev = prev;
386	            if let Some(p) = prev {
387	                self.elems[p].next = Some(slot);
388	            } else {
389	                self.first = Some(slot);
390	            }
391	            self.elems[head_slot].prev = Some(slot);
392	        } else {
393	            // Append to the head of the all-elements list.
394	            self.elems[slot].next = self.first;
395	            if let Some(f) = self.first {
396	                self.elems[f].prev = Some(slot);
397	            }
398	            self.elems[slot].prev = None;
399	            self.first = Some(slot);
400	        }
401	    }
402	
403	    /// `removeElement` (hash.c:188-216).
404	    fn remove_with_hash(&mut self, h: u32) {
405	        // Locate the slot. We need the key for str_icmp, so we use
406	        // find_slot equivalent logic.
407	        let slot = self.find_slot_by_hash(h);
408	        if let Some(slot) = slot {
409	            self.remove_slot(slot);
410	        }
411	    }
412	
413	    fn find_slot_by_hash(&self, h: u32) -> Option<usize> {
414	        if self.htsize > 0 {
415	            let idx = (h % self.htsize) as usize;
416	            let entry = &self.ht[idx];
417	            let mut count = entry.count;
418	            let mut cur = entry.chain;
419	            while count > 0 {
420	                let slot = cur?;
421	                let e = &self.elems[slot];
422	                if e.h == h {
423	                    return Some(slot);
424	                }
425	                cur = e.next;
426	                count -= 1;
427	            }
428	        }
429	        let mut count = self.count;
430	        let mut cur = self.first;
431	        while count > 0 {
432	            let slot = cur?;
433	            let e = &self.elems[slot];
434	            if e.h == h {
435	                return Some(slot);
436	            }
437	            cur = e.next;
438	            count -= 1;
439	        }
440	        None
441	    }
442	
443	    fn remove_slot(&mut self, slot: usize) {
444	        // Unlink from all-elements list.
445	        let (next, prev) = {
446	            let e = &self.elems[slot];
447	            (e.next, e.prev)
448	        };
449	        if let Some(p) = prev {
450	            self.elems[p].next = next;
451	        } else {
452	            self.first = next;
453	        }
454	        if let Some(n) = next {
455	            self.elems[n].prev = prev;
456	        }
457	        // Unlink from bucket chain (hash.c:201-208).
458	        if self.htsize > 0 {
459	            let h = self.elems[slot].h;
460	            let idx = (h % self.htsize) as usize;
461	            let entry = &mut self.ht[idx];
462	            if entry.chain == Some(slot) {
463	                entry.chain = next;
464	            }
465	            entry.count -= 1;
466	        }
467	        // Free the slot.
468	        let free = self.elems[slot].next; // temporarily reuse `next`
469	        // Actually we need to push `slot` onto the free list. The
470	        // `next` field has been used for the live list — re-purpose
471	        // it as the free-list link.
472	        self.elems[slot].used = false;
473	        self.elems[slot].p_key.clear();
474	        self.elems[slot].data = ptr::null_mut();
475	        self.elems[slot].next = self.free_head;
476	        self.elems[slot].prev = None;
477	        self.free_head = Some(slot);
478	        let _ = free; // silence unused warning
479	        self.count -= 1;
480	        if self.count == 0 {
481	            // hash.c:211-215 — drop everything when empty.
482	            self.ht.clear();
483	            self.htshrink_to_fit();
484	            self.htsize = 0;
485	            self.first = None;
486	            self.elems.clear();
487	            self.free_head = None;
488	        }
489	    }
490	
491	    /// `rehash` (hash.c:113-146).
492	    ///
493	    /// Grows the bucket array to at least `new_size` slots. No-op when
494	    /// `new_size == 0` or allocation fails (matching the C version's
495	    /// "performance hit but not fatal" stance).
496	    fn rehash(&mut self, new_size: u32) -> bool {
497	        if new_size == 0 {
498	            return false;
499	        }
500	        let new_size = if new_size < 8 { 8 } else { new_size };
501	        // Allocate new bucket array; if it fails, the C version
502	        // returns 0 (no resize) and keeps the old one.
503	        let mut new_ht = vec![HashEntry::default(); new_size as usize];
504	        // Snapshot the all-elements list, then re-insert.
505	        let saved_first = self.first;
506	        self.first = None;
507	        let mut cur = saved_first;
508	        while let Some(slot) = cur {
509	            let next = self.elems[slot].next;
510	            let h = self.elems[slot].h;
511	            // Detach from current list before re-inserting.
512	            self.elems[slot].next = None;
513	            self.elems[slot].prev = None;
514	            // Insert into new bucket.
515	            let bucket = (h % new_size) as usize;
516	            let head = if new_ht[bucket].count > 0 {
517	                new_ht[bucket].chain
518	            } else {
519	                None
520	            };
521	            new_ht[bucket].count += 1;
522	            new_ht[bucket].chain = Some(slot);
523	            if let Some(head_slot) = head {
524	                let prev = self.elems[head_slot].prev;
525	                self.elems[slot].next = Some(head_slot);
526	                self.elems[slot].prev = prev;
527	                if let Some(p) = prev {
528	                    self.elems[p].next = Some(slot);
529	                } else {
530	                    self.first = Some(slot);
531	                }
532	                self.elems[head_slot].prev = Some(slot);
533	            } else {
534	                self.elems[slot].next = self.first;
535	                if let Some(f) = self.first {
536	                    self.elems[f].prev = Some(slot);
537	                }
538	                self.elems[slot].prev = None;
539	                self.first = Some(slot);
540	            }
541	            cur = next;
542	        }
543	        self.ht = new_ht;
544	        self.htsize = new_size;
545	        true
546	    }
547	
548	    fn alloc_slot(&mut self) -> Option<usize> {
549	        if let Some(slot) = self.free_head {
550	            self.free_head = self.elems[slot].next;
551	            return Some(slot);
552	        }
553	        // Grow the pool. Vec::push cannot fail in practice (caller
554	        // catches abort via the process exit), but we model the
555	        // OOM path by checking capacity. We pre-allocate to avoid
556	        // the abort.
557	        let len = self.elems.len();
558	        let new_cap = (len + 1).next_power_of_two().max(8);
559	        if self.elems.capacity() < new_cap {
560	            // Vec::reserve may abort on OOM on the default allocator;
561	            // we treat that as the OOM path: return None and let
562	            // the caller bail.
563	            // SAFETY NOTE: this is best-effort — on the system
564	            // allocator there is no recoverable OOM in Rust. The
565	            // contract documented in `02-c-porting-conventions.md`
566	            // §3 only requires "realloc on OOM returns null, original
567	            // pointer preserved" — for `Vec::push` of a single
568	            // element that has no prior slot, there is no prior
569	            // pointer to preserve.
570	            self.elems.reserve(new_cap - self.elems.capacity());
571	        }
572	        self.elems.push(HashElem {
573	            p_key: String::new(),
574	            h: 0,
575	            data: ptr::null_mut(),
576	            next: None,
577	            prev: None,
578	            used: true,
579	        });
580	        Some(self.elems.len() - 1)
581	    }
582	
583	    fn htshrink_to_fit(&mut self) {
584	        self.ht.shrink_to_fit();
585	    }
586	}
