588	// ============================================================================
589	// HashIter — iterate (key, data) pairs in insertion order
590	// ============================================================================
591	
592	/// Result of a `find_with_hash` lookup.
593	#[derive(Clone, Copy)]
594	pub struct FindResult {
595	    /// The stored data pointer (null on miss).
596	    pub data: *mut u8,
597	    /// The computed hash of the key.
598	    pub h: u32,
599	    /// `true` if a matching element was found.
600	    pub found: bool,
601	}
602	
603	/// Iterator over a `Hash` in insertion order.
604	pub struct HashIter<'a> {
605	    ht: &'a Hash,
606	    cur: Option<usize>,
607	}
608	
609	impl<'a> Iterator for HashIter<'a> {
610	    type Item = (&'a str, *mut u8);
611	
612	    fn next(&mut self) -> Option<Self::Item> {
613	        let slot = self.cur?;
614	        let e = &self.ht.elems[slot];
615	        let key = e.p_key.as_str();
616	        let data = e.data;
617	        self.cur = e.next;
618	        Some((key, data))
619	    }
620	}
