622	// ============================================================================
623	// Case-insensitive ASCII comparison — matches C `sqlite3StrICmp`
624	// ============================================================================
625	
626	#[inline]
627	fn str_icmp(a: &str, b: &str) -> i32 {
628	    // Mirror sqlite3StrICmp semantics: case-insensitive on ASCII
629	    // A-Z / a-z, byte-equal otherwise. Empty strings are equal.
630	    let ab = a.as_bytes();
631	    let bb = b.as_bytes();
632	    let n = ab.len().min(bb.len());
633	    for i in 0..n {
634	        let mut x = ab[i];
635	        let mut y = bb[i];
636	        if x >= b'A' && x <= b'Z' {
637	            x += 0x20;
638	        }
639	        if y >= b'A' && y <= b'Z' {
640	            y += 0x20;
641	        }
642	        if x != y {
643	            return (x as i32) - (y as i32);
644	        }
645	    }
646	    (ab.len() as i32) - (bb.len() as i32)
647	}
