649	// ============================================================================
650	// Integer-to-string conversion (avoids pulling in `itoa` crate)
651	// ============================================================================
652	
653	fn itoa_buf() -> [u8; 20] {
654	    [0u8; 20]
655	}
656	
657	fn format_i64(mut n: i64, buf: &mut [u8; 20]) -> &str {
658	    // Use the buffer as scratch from the back.
659	    let negative = n < 0;
660	    // Handle i64::MIN specially to avoid overflow on -n.
661	    if negative {
662	        n = n.wrapping_neg();
663	    }
664	    let mut i = buf.len();
665	    if n == 0 {
666	        i -= 1;
667	        buf[i] = b'0';
668	    } else {
669	        while n > 0 && i > 0 {
670	            i -= 1;
671	            buf[i] = b'0' + (n % 10) as u8;
672	            n /= 10;
673	        }
674	    }
675	    if negative && i > 0 {
676	        i -= 1;
677	        buf[i] = b'-';
678	    }
679	    // SAFETY: we only ever write ASCII digits and an optional '-'.
680	    std::str::from_utf8(&buf[i..]).unwrap()
681	}
