683	// ============================================================================
684	// GrowableArray<T> — dynamic array with capacity doubling
685	// ============================================================================
686	
687	/// Generic growable array.
688	///
689	/// Mirrors the role of `GrowableArray` in SQLite's C source
690	/// (used e.g. in `where.c` and `vdbemem.c`):
691	/// - Starts at capacity 0
692	/// - On `push`, doubles the capacity when full
693	/// - On `remove`, halves the capacity when `count < capacity/4` and
694	///   capacity > `MIN_CAPACITY`
695	///
696	/// This is **not** a 1:1 port of any specific C `GrowableArray`
697	/// (the C version lives in a few different files and the contracts
698	/// differ). It is a Rust-idiomatic equivalent used by Rust-side code
699	/// that needs a growable vector with deterministic capacity behavior.
700	pub struct GrowableArray<T> {
701	    data: Vec<Option<T>>,
702	    count: u32,
703	    capacity: u32,
704	}
705	
706	/// Minimum capacity to avoid thrashing on a 0 → 1 → 0 sequence.
707	const GROWABLE_MIN_CAPACITY: u32 = 4;
708	
709	impl<T> GrowableArray<T> {
710	    /// Construct a new, empty growable array.
711	    pub const fn new() -> Self {
712	        Self {
713	            data: Vec::new(),
714	            count: 0,
715	            capacity: 0,
716	        }
717	    }
718	
719	    /// Construct with a given initial capacity.
720	    pub fn with_capacity(cap: usize) -> Self {
721	        let cap = cap.max(GROWABLE_MIN_CAPACITY as usize) as u32;
722	        let mut data = Vec::with_capacity(cap as usize);
723	        data.resize_with(cap as usize, || None);
724	        Self {
725	            data,
726	            count: 0,
727	            capacity: cap,
728	        }
729	    }
730	
731	    /// Number of live elements.
732	    pub fn len(&self) -> u32 {
733	        self.count
734	    }
735	
736	    /// `true` when there are no live elements.
737	    pub fn is_empty(&self) -> bool {
738	        self.count == 0
739	    }
740	
741	    /// Current capacity (number of slots, live or tombstone).
742	    pub fn capacity(&self) -> u32 {
743	        self.capacity
744	    }
745	
746	    /// Append `value`, doubling the capacity if necessary. Returns
747	    /// the new index.
748	    ///
749	    /// OOM (in the sense of `Vec` abort-on-alloc-failure) is not
750	    /// recoverable; the array is left untouched on failure. We expose
751	    /// a `try_push` for fallible allocation.
752	    pub fn push(&mut self, value: T) -> u32 {
753	        let idx = match self.try_push(value) {
754	            Ok(i) => i,
755	            Err(_) => {
756	                // On the system allocator, Vec::push cannot fail
757	                // short of an abort; for completeness we fall back
758	                // to panicking with a descriptive message.
759	                panic!("GrowableArray: out of memory");
760	            }
761	        };
762	        idx
763	    }
764	
765	    /// Fallible `push` — returns `Err(SqliteError::NOMEM)` on
766	    /// allocation failure (modeled; the system allocator aborts
767	    /// in practice).
768	    pub fn try_push(&mut self, value: T) -> SqliteResult<u32> {
769	        if self.count == self.capacity {
770	            // Double. Guard against 0 → 1.
771	            let new_cap = if self.capacity == 0 {
772	                GROWABLE_MIN_CAPACITY
773	            } else {
774	                self.capacity.saturating_mul(2)
775	            };
776	            self.resize_to(new_cap)?;
777	        }
778	        // Find first free slot (linear scan from 0). After doubling,
779	        // the new slots are at the end and are all `None`.
780	        let mut idx = 0u32;
781	        while idx < self.capacity {
782	            if self.data[idx as usize].is_none() {
783	                self.data[idx as usize] = Some(value);
784	                self.count += 1;
785	                return Ok(idx);
786	            }
787	            idx += 1;
788	        }
789	        // Should not be reachable: we just resized.
790	        Err(SqliteError::ERROR)
791	    }
792	
793	    /// Get a reference to the element at `idx`.
794	    pub fn get(&self, idx: u32) -> Option<&T> {
795	        self.data.get(idx as usize).and_then(|s| s.as_ref())
796	    }
797	
798	    /// Remove the element at `idx`, returning the value. Shrinks the
799	    /// capacity when `count < capacity / 4` and capacity is above the
800	    /// minimum threshold.
801	    pub fn remove(&mut self, idx: u32) -> Option<T> {
802	        if idx >= self.capacity {
803	            return None;
804	        }
805	        let v = self.data[idx as usize].take()?;
806	        self.count -= 1;
807	        if self.capacity > GROWABLE_MIN_CAPACITY
808	            && self.count < self.capacity / 4
809	        {
810	            let new_cap = (self.capacity / 2).max(GROWABLE_MIN_CAPACITY);
811	            let _ = self.resize_to(new_cap); // best-effort shrink
812	        }
813	        Some(v)
814	    }
815	
816	    /// Iterate live elements in slot order (lower index first).
817	    pub fn iter(&self) -> impl Iterator<Item = (u32, &T)> {
818	        self.data
819	            .iter()
820	            .enumerate()
821	            .filter_map(|(i, s)| s.as_ref().map(|v| (i as u32, v)))
822	    }
823	
824	    /// Drain all elements, returning an iterator of owned values.
825	    pub fn drain(&mut self) -> impl Iterator<Item = T> + '_ {
826	        self.count = 0;
827	        self.data.drain(..).filter_map(|s| s)
828	    }
829	
830	    /// Resize the backing storage to `new_cap` slots. New slots are
831	    /// `None`. If `new_cap` is smaller than `count`, this truncates
832	    /// (in slot order) — useful for tests of the boundary case.
833	    fn resize_to(&mut self, new_cap: u32) -> SqliteResult<()> {
834	        let new_cap = new_cap as usize;
835	        if new_cap > self.data.len() {
836	            // Vec cannot return OOM on the system allocator; we
837	            // pre-check the layout and accept the abort.
838	            self.data.resize_with(new_cap, || None);
839	            self.capacity = new_cap as u32;
840	        } else if new_cap < self.data.len() {
841	            // Truncate from the end. Adjust count if we drop live
842	            // elements (we choose the policy: drop highest slots).
843	            for slot in self.data[new_cap..].iter_mut() {
844	                if slot.is_some() {
845	                    self.count -= 1;
846	                }
847	            }
848	            self.data.truncate(new_cap);
849	            self.capacity = new_cap as u32;
850	        }
851	        Ok(())
852	    }
853	}
854	
855	impl<T> Default for GrowableArray<T> {
856	    fn default() -> Self {
857	        Self::new()
858	    }
859	}
860	
861	impl<T> Drop for GrowableArray<T> {
862	    fn drop(&mut self) {
863	        // Vec drops its elements automatically.
864	    }
865	}
