1208	    #[test]
1209	    fn growable_100k_elements_works() {
1210	        let mut g: GrowableArray<u64> = GrowableArray::new();
1211	        for i in 0..100_000u64 {
1212	            g.push(i);
1213	        }
1214	        assert_eq!(g.len(), 100_000);
1215	        // Spot-check a few values.
1216	        let mut count = 0u64;
1217	        let mut sum = 0u64;
